class Solution:
    def countKeyChanges(self, s: str) -> int:
        count = 0
        # Iterate through the string starting from the second character
        for i in range(1, len(s)):
            # Compare current character with the previous one case-insensitively
            # .lower() ensures that 'a' and 'A' are treated as the same key
            if s[i].lower() != s[i - 1].lower():
                count += 1
        return count

from typing import List

class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        max_diag_sq = 0
        max_area = 0

        for length, width in dimensions:
            # Calculate squared diagonal to avoid floating point issues
            diag_sq = length * length + width * width
            area = length * width

            if diag_sq > max_diag_sq:
                max_diag_sq = diag_sq
                max_area = area
            elif diag_sq == max_diag_sq:
                max_area = max(max_area, area)

        return max_area

from typing import List

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # Count the number of elements strictly less than k.
        # Since we always remove the smallest element, we will remove all elements < k
        # before any element >= k is removed. We stop as soon as the smallest element >= k.
        return sum(1 for num in nums if num < k)

from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        m = len(pattern)
        count = 0

        # A subarray matching the pattern has length m + 1.
        # We iterate through all possible starting positions i for such subarrays.
        # The subarray spans indices from i to i + m.
        # Valid i ranges from 0 to n - m - 1.
        for i in range(n - m):
            match = True
            for k in range(m):
                # Check the relationship between the current element and the next element
                # nums[i + k] is the current element relative to pattern index k
                # nums[i + k + 1] is the next element
                val_curr = nums[i + k]
                val_next = nums[i + k + 1]

                if pattern[k] == 1:
                    # Condition: nums[i + k + 1] > nums[i + k]
                    if not (val_next > val_curr):
                        match = False
                        break
                elif pattern[k] == 0:
                    # Condition: nums[i + k + 1] == nums[i + k]
                    if not (val_next == val_curr):
                        match = False
                        break
                elif pattern[k] == -1:
                    # Condition: nums[i + k + 1] < nums[i + k]
                    if not (val_next < val_curr):
                        match = False
                        break

            if match:
                count += 1

        return count

