def main():
    # Read all input from standard input
    # split() handles both spaces and newlines automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # Create an iterator to process the input tokens sequentially
    iterator = iter(input_data)

    # The first token is the number of matches, N
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    takahashi_total = 0
    aoki_total = 0

    # Loop N times to read the scores for each match
    for _ in range(n):
        try:
            # Read X_i (Takahashi's score) and Y_i (Aoki's score)
            x = int(next(iterator))
            y = int(next(iterator))

            takahashi_total += x
            aoki_total += y
        except StopIteration:
            break

    # Compare the total scores and print the winner
    if takahashi_total > aoki_total:
        print("Takahashi")
    elif aoki_total > takahashi_total:
        print("Aoki")
    else:
        print("Draw")

if __name__ == '__main__':
    main()

from typing import List

class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        count = 0
        n = len(words)
        for i in range(n):
            for j in range(i + 1, n):
                # Check if words[i] is both a prefix and a suffix of words[j]
                if self.isPrefixAndSuffix(words[i], words[j]):
                    count += 1
        return count

    def isPrefixAndSuffix(self, s1: str, s2: str) -> bool:
        # If s1 is longer than s2, it cannot be a prefix or suffix of s2
        if len(s1) > len(s2):
            return False
        # Check if s1 is both a prefix and a suffix of s2
        return s2.startswith(s1) and s2.endswith(s1)

