class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # Calculate the XOR sum of all elements in the array
        current_xor = 0
        for num in nums:
            current_xor ^= num

        # We need to transform the current_xor to k.
        # The bits that need to be flipped are those where current_xor differs from k.
        # This is represented by the set bits in (current_xor ^ k).
        # Each set bit corresponds to one operation (flipping that bit in any element).
        return bin(current_xor ^ k).count('1')

