import sys

def solve():
    # Read all input from standard input at once and split by whitespace
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # Create an iterator to process the tokens sequentially
    iterator = iter(input_data)

    try:
        # The first token is N, the number of vertices
        N = int(next(iterator))
    except StopIteration:
        return

    # Process each row of the adjacency matrix
    # There are N rows, corresponding to vertices 1 to N
    for i in range(N):
        neighbors = []
        # Iterate through each column to find connected vertices
        # There are N columns, corresponding to vertices 1 to N
        for j in range(N):
            try:
                val = int(next(iterator))
            except StopIteration:
                break

            # If A_{i,j} is 1, there is an edge between vertex i+1 and j+1
            if val == 1:
                neighbors.append(j + 1)

        # Print the neighbors separated by a space
        # The print function with * unpacking handles the space separation
        print(*(neighbors))

if __name__ == '__main__':
    solve()

import sys

def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # The first token is the string S
    S = input_data[0]
    n = len(S)

    # Iterate through each character to find the unique one
    for i in range(n):
        is_unique = True
        # Check if S[i] differs from all other characters
        for j in range(n):
            if i == j:
                continue
            if S[i] == S[j]:
                # If we find a match, S[i] is not the unique character
                is_unique = False
                break

        # If S[i] is unique, print its 1-based index and exit
        if is_unique:
            print(i + 1)
            return

