import sys

def solve():
    # Read all input from standard input efficiently
    # sys.stdin.read().split() reads the whole input and splits by whitespace
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # The first token is N
        N = int(next(iterator))
    except StopIteration:
        return

    # Dictionary to store the minimum deliciousness for each color
    # Key: Color (int), Value: Minimum Deliciousness (int)
    min_deliciousness_by_color = {}

    # Iterate through each bean
    for _ in range(N):
        try:
            a = int(next(iterator))
            c = int(next(iterator))

            # Update the minimum deliciousness for color c
            # If color c is already in the dictionary, we take the minimum of the existing value and a
            # If not, we initialize it with a
            if c in min_deliciousness_by_color:
                if a < min_deliciousness_by_color[c]:
                    min_deliciousness_by_color[c] = a
            else:
                min_deliciousness_by_color[c] = a
        except StopIteration:
            break

    # The problem asks to maximize the minimum possible deliciousness of the bean eaten.
    # This corresponds to maximizing the minimum deliciousness among beans of a chosen color.
    # We have computed the minimum deliciousness for each color.
    # We simply find the maximum among these values.

    if min_deliciousness_by_color:
        result = max(min_deliciousness_by_color.values())
        print(result)
    else:
        # Given constraints N >= 1, this block is technically unreachable.
        print(0)

if __name__ == '__main__':
    solve()

class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        if len(nums) <= 1:
            return len(nums)

        max_len = 1
        curr_inc = 1
        curr_dec = 1

        for i in range(1, len(nums)):
            if nums[i] > nums[i-1]:
                curr_inc += 1
                curr_dec = 1
            elif nums[i] < nums[i-1]:
                curr_dec += 1
                curr_inc = 1
            else:
                curr_inc = 1
                curr_dec = 1

            max_len = max(max_len, curr_inc, curr_dec)

        return max_len

