from typing import List

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        # Dictionary to store the count of how many strings in arr contain each substring
        freq = {}

        # Populate the frequency map by iterating through all strings and their substrings
        for s in arr:
            length_s = len(s)
            # Generate all substrings of s
            for i in range(length_s):
                for j in range(i + 1, length_s + 1):
                    sub = s[i:j]
                    freq[sub] = freq.get(sub, 0) + 1

        ans = []
        # For each string, find the shortest substring that is unique to it
        for s in arr:
            length_s = len(s)
            found = False
            # Iterate through lengths from 1 to length_s to ensure we find the shortest first
            for l in range(1, length_s + 1):
                candidates = []
                # Generate all substrings of length l
                for i in range(length_s - l + 1):
                    sub = s[i : i + l]
                    # If the substring appears in exactly one string (which is the current one), it is valid
                    if freq[sub] == 1:
                        candidates.append(sub)

                # If we found any valid substrings of this length, pick the lexicographically smallest
                if candidates:
                    ans.append(min(candidates))
                    found = True
                    break

            # If no unique substring was found for this string, append an empty string
            if not found:
                ans.append("")

        return ans

