class Solution:
    def scoreOfString(self, s: str) -> int:
        score = 0
        # Iterate through the string up to the second to last character
        for i in range(len(s) - 1):
            # Calculate the absolute difference between ASCII values of adjacent characters
            score += abs(ord(s[i]) - ord(s[i+1]))
        return score

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        left = 0
        max_len = 0
        counts = {}

        for right in range(len(s)):
            char = s[right]
            counts[char] = counts.get(char, 0) + 1

            # If the current character appears more than twice, shrink the window from the left
            while counts[char] > 2:
                left_char = s[left]
                counts[left_char] -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

        return max_len

class Solution:
    def numberOfSpecialChars(self, word: str) -> int:
        # Create a set of all unique characters present in the word for O(1) lookups
        unique_chars = set(word)

        count = 0
        # Iterate through each lowercase letter of the English alphabet
        for char in "abcdefghijklmnopqrstuvwxyz":
            # A letter is special if both its lowercase and uppercase forms exist in the word
            if char in unique_chars and char.upper() in unique_chars:
                count += 1

        return count

class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        # Dictionary to map each character in t to its index for O(1) lookup
        t_indices = {char: i for i, char in enumerate(t)}

        permutation_diff = 0

        # Iterate through string s
        for i, char in enumerate(s):
            # Find the index of the character in string t
            # Since t is a permutation of s, char is guaranteed to be in t_indices
            index_in_t = t_indices[char]

            # Add the absolute difference between the index in s and index in t
            permutation_diff += abs(i - index_in_t)

        return permutation_diff

