from collections import Counter

class Solution:
    def duplicateNumbersXOR(self, nums: List[int]) -> int:
        # Count the frequency of each number in the array
        counts = Counter(nums)

        xor_sum = 0

        # Iterate over the unique numbers and their counts
        for num, count in counts.items():
            # If a number appears exactly twice, XOR it to the sum
            if count == 2:
                xor_sum ^= num

        return xor_sum

