class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        # Determine the maximum number of columns to handle jagged arrays if necessary.
        # If the grid is rectangular, this will be len(grid[0]).
        max_cols = 0
        for r in range(rows):
            if len(grid[r]) > max_cols:
                max_cols = len(grid[r])

        # Initialize counts for rows and columns
        row_counts = [0] * rows
        col_counts = [0] * max_cols

        # First pass: Count 1s in each row and column
        for r in range(rows):
            for c in range(len(grid[r])):
                if grid[r][c] == 1:
                    row_counts[r] += 1
                    col_counts[c] += 1

        ans = 0
        # Second pass: Calculate the number of right triangles
        for r in range(rows):
            for c in range(len(grid[r])):
                if grid[r][c] == 1:
                    # If grid[r][c] is 1, it can be the vertex with the right angle.
                    # We need to pick another 1 from the same row and another 1 from the same column.
                    # The number of ways to pick the other two vertices is:
                    # (number of other 1s in this row) * (number of other 1s in this column)
                    # Since row_counts[r] includes grid[r][c], we subtract 1.
                    ans += (row_counts[r] - 1) * (col_counts[c] - 1)

        return ans

