    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        # Iterate through all possible 2x2 subgrids in the 3x3 grid.
        # The top-left corner (r, c) of a 2x2 subgrid can range from (0,0) to (1,1).
        for r in range(2):
            for c in range(2):
                # Count occurrences of 'B' and 'W' in the current subgrid
                b_count = 0
                w_count = 0

                # The subgrid cells are at (r, c), (r, c+1), (r+1, c), (r+1, c+1)
                for i in range(2):
                    for j in range(2):
                        if grid[r + i][c + j] == 'B':
                            b_count += 1
                        else:
                            w_count += 1

                # If a subgrid has 3 or more 'B's or 3 or more 'W's,
                # we can change at most 1 cell to make it monochromatic.
                # (If 4, 0 changes; if 3, 1 change).
                if b_count >= 3 or w_count >= 3:
                    return True

        return False

