class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at cell 0, which corresponds to row 0, column 0
        row, col = 0, 0

        for command in commands:
            if command == "UP":
                row -= 1
            elif command == "DOWN":
