class Solution:
    def minChanges(self, n: int, k: int) -> int:
        # Check if all bits set in k are also set in n.
        # If (n & k) != k, it means k has a bit set to 1 where n has a 0.
        # Since we can only change 1s to 0s, this transformation is impossible.
        if (n & k) != k:
            return -1

        # If the condition is met, we need to count the number of bits that are 1 in n
        # but 0 in k. These are the bits that need to be flipped from 1 to 0.
        # This corresponds to the number of set bits in (n ^ k).
        return bin(n ^ k).count('1')

