class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # Calculate the number of flips required to make all rows palindromic.
        # For each row, we check pairs (j, n-1-j) for j in 0 to n/2 - 1.
        row_flips = 0
        for r in range(m):
            for c in range(n // 2):
                if grid[r][c] != grid[r][n - 1 - c]:
                    row_flips += 1

        # Calculate the number of flips required to make all columns palindromic.
        # For each column, we check pairs (r, m-1-r) for r in 0 to m/2 - 1.
        col_flips = 0
        for c in range(n):
            for r in range(m // 2):
                if grid[r][c] != grid[m - 1 - r][c]:
                    col_flips += 1

        # Return the minimum of the two costs.
        return min(row_flips, col_flips)

