class Solution:
    def clearDigits(self, s: str) -> str:
        stack = []
        for char in s:
            if char.isdigit():
                # If we encounter a digit, remove the closest non-digit to its left.
                # The top of the stack is the closest non-digit to the left.
                if stack:
                    stack.pop()
                # The digit is discarded.
            else:
                # Non-digit characters are kept (added to stack).
                stack.append(char)
