class Solution:
    def checkTwoChessboards(self, coordinate1: str, coordinate2: str) -> bool:
        # Helper function to calculate the parity of the sum of column and row indices
        def get_color_parity(coord: str) -> int:
            # Convert column letter to 0-7 index (e.g., 'a' -> 0, 'h' -> 7)
            col_index = ord(coord[0]) - ord('a')
            # Convert row number to 0-7 index (e.g., '1' -> 0, '8' -> 7)
