from typing import List

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        heap = []
        results = []

        for x, y in queries:
            dist = abs(x) + abs(y)

            if len(heap) < k:
                # If we haven't collected k obstacles yet, add the current one.
                heapq.heappush(heap, -dist)

                # If after adding, we still have fewer than k obstacles, return -1.
                if len(heap) < k:
                    results.append(-1)
                else:
                    # If we just reached k obstacles, the k-th nearest is the max in the heap.
                    results.append(-heap[0])
            else:
                # If we already have k obstacles, check if the new obstacle should be included.
                # We include it if it is closer than the current k-th nearest obstacle (max in heap).
                max_val = -heap[0]
                if dist < max_val:
                    heapq.heapreplace(heap, -dist)

                # The k-th nearest obstacle is the max in the heap.
                results.append(-heap[0])

        return results

