        current_len = 0

        for i in range(n):
            # Check if the current element continues the consecutive sequence from the previous one
            if i > 0 and nums[i] == nums[i-1] + 1:
                current_len += 1
            else:
                # If not consecutive, the sequence resets to just the current element
                current_len = 1

            # Once we have processed at least k elements (index >= k-1), we can check the window ending here
            if i >= k - 1:
