    n = len(floors)

    # Iterate over all unique pairs of distinct floor cells.
    # Since H, W <= 10, the number of floor cells n is at most 100.
    # The complexity will be O(n^3), which is roughly 10^6 operations.
    # This is well within the time limit.

    for i in range(n):
        r1, c1 = floors[i]
        for j in range(i + 1, n):
            r2, c2 = floors[j]

