class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        # Calculate the total sum of the array
        total_sum = sum(nums)
        # Count the frequency of each number in the array
        counts = collections.Counter(nums)

        # Initialize max_outlier to a very small number
        max_outlier = -float('inf')

        # Iterate through each element in the array considering it as a potential outlier
        for v in nums:
            # If v is the outlier, then the sum element u must satisfy:
            # v = total_sum - 2 * u  =>  u = (total_sum - v) / 2

            diff = total_sum - v
            # If (total_sum - v) is odd, u cannot be an integer
            if diff % 2 != 0:
                continue

            u = diff // 2

            # Check if u exists in the array
            if counts[u] > 0:
                if u == v:
                    # If u == v, we need at least two occurrences of v in the array
                    # to assign distinct indices for the sum element and the outlier.
                    if counts[u] > 1:
                        if v > max_outlier:
                            max_outlier = v
                else:
                    # If u != v, then any occurrence of u is guaranteed to be at a
                    # different index than v (since nums[j] = v != u).
                    if v > max_outlier:
                        max_outlier = v

        return max_outlier

class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)

        for l, r in queries:
            diff[l] += 1
            diff[r + 1] -= 1

