from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        num_rows = len(grid)
        num_cols = len(grid[0])

        # Traverse the grid in zigzag pattern
        for r in range(num_rows):
            # If row index is even, move left to right
            if r % 2 == 0:
                for c in range(num_cols):
                    result.append(grid[r][c])
            # If row index is odd, move right to left
            else:
                for c in range(num_cols - 1, -1, -1):
                    result.append(grid[r][c])

        # Skip every alternate cell (keep elements at indices 0, 2, 4, ...)
        return result[::2]

