import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # Parse N
    try:
        n = int(input_data[0])
    except ValueError:
        return

    # Iterate over each row r from 1 to N
    for r in range(1, n + 1):
        row_chars = []
        # Iterate over each column c from 1 to N
        for c in range(1, n + 1):
            # Calculate K = min(r, c, N + 1 - r, N + 1 - c)
            # This K represents the largest step index i that covers cell (r, c).
            # The color is determined by the parity of K.
            k = min(r, c, n + 1 - r, n + 1 - c)

            # If K is odd, the cell is colored black ('#')
            # If K is even, the cell is colored white ('.')
            if k % 2 == 1:
                row_chars.append('#')
            else:
                row_chars.append('.')

        # Print the constructed row string
        print("".join(row_chars))

