from collections import Counter

class Solution:
    def maxDifference(self, s: str) -> int:
        # Count the frequency of each character in the string
        counts = Counter(s)

        # Initialize variables to track the maximum odd frequency and minimum even frequency
        # max_odd starts at 0 because frequencies are at least 1
        # min_even starts at infinity because we want the minimum
        max_odd = 0
        min_even = float('inf')

        # Iterate through the frequencies of all characters
        for freq in counts.values():
            if freq % 2 == 1:
                # If the frequency is odd, update max_odd
                if freq > max_odd:
                    max_odd = freq
            else:
                # If the frequency is even, update min_even
                if freq < min_even:
                    min_even = freq

        # Return the difference as defined: (max odd frequency) - (min even frequency)
        return max_odd - min_even

