from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        used = [False] * n  # Track which baskets have been used
        unplaced = 0

        # Process each fruit type from left to right
        for i in range(n):
            fruit_quantity = fruits[i]
            placed = False

            # Find the leftmost available basket with sufficient capacity
            for j in range(n):
                if not used[j] and baskets[j] >= fruit_quantity:
                    used[j] = True  # Mark this basket as used
                    placed = True
                    break

            if not placed:
                unplaced += 1

        return unplaced

from typing import List

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        # Calculate the total sum of the array
        total_sum = sum(nums)

        # If the total sum is even, then for any partition, the difference between 
        # the sum of the left and right subarrays is even.
        # If the total sum is odd, the difference is always odd.
        # The number of valid partitions is (n - 1) if total_sum is even, else 0.
        if total_sum % 2 == 0:
            return len(nums) - 1
        else:
            return 0

