class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Maximum possible value for group size and element value is 100,000
        MAX_VAL = 100001

        # Step 1: Precompute the first occurrence index for each element value
        # Initialize with -1 to indicate the value is not present
        first_occurrence = [-1] * MAX_VAL
        for idx, val in enumerate(elements):
            if first_occurrence[val] == -1:
                first_occurrence[val] = idx

        # Step 2: Precompute divisors for all numbers up to MAX_VAL
        # This allows us to quickly retrieve all divisors for any group size
        divisors = [[] for _ in range(MAX_VAL)]
        for i in range(1, MAX_VAL):
            # Iterate through multiples of i: i, 2*i, 3*i, ...
            for j in range(i, MAX_VAL, i):
                divisors[j].append(i)

        # Step 3: Assign elements to groups
        assigned = []
        for g in groups:
            best_idx = -1
            # Iterate through all divisors of the current group size
            for d in divisors[g]:
                # If the divisor d exists in the elements array, get its first occurrence index
                idx = first_occurrence[d]
                if idx != -1:
                    # We want the element with the smallest index j
                    if best_idx == -1 or idx < best_idx:
                        best_idx = idx

            assigned.append(best_idx)

        return assigned

