from typing import List

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            is_good = True

            # Check left neighbor condition: nums[i] must be > nums[i-k] if i-k exists
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check right neighbor condition: nums[i] must be > nums[i+k] if i+k exists
            # We only check if is_good is still True to optimize slightly, though not strictly necessary
            if is_good and i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total_sum += nums[i]

        return total_sum

from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        memo = {}

        def dp(i):
            remaining = n - i

            if remaining <= 0:
                return 0

            if remaining <= 2:
                return max(nums[i:])

            if i in memo:
                return memo[i]

            # First 3 elements are at indices i, i+1, i+2
            a, b, c = nums[i], nums[i+1], nums[i+2]

            # Option 1: remove a and b (indices i and i+1)
            cost1 = max(a, b) + dp(i + 2)

            # Option 2: remove a and c (indices i and i+2)
            cost2 = max(a, c) + dp(i + 1)

            # Option 3: remove b and c (indices i+1 and i+2)
            cost3 = max(b, c) + dp(i + 1)

            result = min(cost1, cost2, cost3)
            memo[i] = result
            return result

        return dp(0)
